window.kbPageData["views/entry/k-91af0376506dec50"] = {"key":"entry/k-91af0376506dec50","state":{"route":"entry/k-91af0376506dec50"},"node":{"id":"k-91af0376506dec50","mode":"k","title":"交付商品不符合约定的违约责任","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["交付商品缺少约定功能属于履行不符合约定，可请求承担违约责任"],"qs":["江苏 2025 B类 行测#17"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"卖方交付的商品不具备买卖合同约定的功能，属于履行不符合约定，买方可以请求卖方承担违约责任。","review":{"definition":"卖方交付的商品不具备买卖合同约定的功能，属于履行不符合约定，买方可以请求卖方承担违约责任。","explanation":"本题将生成临时密码作为销售时承诺的门锁功能。M公司交付的门锁缺少该功能，并要求韩某另付费升级，故其交付不符合约定，D项成立。D项的判断依据是所交付的门锁与约定功能之间的差异。","references":[],"evidence":"M公司的行为构成违约，因此，韩某有权请求M公司承担违约责任。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#17":{"paper":"江苏 2025 B类 行测","n":17,"mod":"常识判断","src":["91e0d9fd02ca7ec6d61f.pdf",4],"asrc":["f2ff67a0f2a2f7e8e926.pdf",7],"card":"e4d47d034c952b8ddf91e4bf","links":[{"id":"k-91af0376506dec50","role":"解题依据","why":"交付的门锁缺少约定功能，构成判断违约责任的事实依据。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-91af0376506dec50":[["江苏 2025 B类 行测#17"]]}};
